import{_ as o,C as h,o as n,c as i,j as t,a as r,E as s,a3 as l}from"./chunks/framework.D6kVjW99.js";const g=JSON.parse('{"title":"What to ask your assistant","description":"Ready-to-copy questions for your AI assistant, grouped by type of business (restaurant, grocery, bakery, shop) and then by moment of the day.","frontmatter":{"title":"What to ask your assistant","description":"Ready-to-copy questions for your AI assistant, grouped by type of business (restaurant, grocery, bakery, shop) and then by moment of the day.","order":93,"role":["OWNER","ADMIN"],"appareil":"WEB","duree":"5 minutes","objectif":"Know what to ask your AI assistant for your business, and copy the question you need.","prerequis":["An assistant already connected to Vendora: see <a href=\\"/en/guide/reglages/brancher-votre-assistant-ia\\">Connect your AI assistant</a>."],"capturesLangue":{},"capturesCouvertes":true},"headers":[],"relativePath":"en/guide/reglages/que-demander.md","filePath":"en/guide/reglages/que-demander.md","lastUpdated":1794456625000}'),d={name:"en/guide/reglages/que-demander.md"};function m(u,e,c,f,y,p){const a=h("FicheTuto");return n(),i("div",null,[e[0]||(e[0]=t("h1",{id:"what-to-ask-your-assistant",tabindex:"-1"},[r("What to ask your assistant "),t("a",{class:"header-anchor",href:"#what-to-ask-your-assistant","aria-label":'Permalink to "What to ask your assistant"'},"​")],-1)),s(a),e[1]||(e[1]=l('<p>Here are questions to ask your assistant (Claude, ChatGPT…) exactly as written. They are grouped by type of business, then by moment of the day; pick the ones that fit your shop.</p><blockquote><p>You do not need to name your store if you only have one. With several stores, just add its name: “… at the grocery store”.</p></blockquote><h2 id="restaurant" tabindex="-1">Restaurant <a class="header-anchor" href="#restaurant" aria-label="Permalink to &quot;Restaurant&quot;">​</a></h2><h3 id="in-the-morning" tabindex="-1">In the morning <a class="header-anchor" href="#in-the-morning" aria-label="Permalink to &quot;In the morning&quot;">​</a></h3><p><em>Before opening: where do things stand after yesterday?</em></p><ul><li>“How much did I make yesterday, and was it better or worse than the day before?”</li><li>“What was my peak hour for sales last week?”</li></ul><h3 id="at-the-end-of-the-day" tabindex="-1">At the end of the day <a class="header-anchor" href="#at-the-end-of-the-day" aria-label="Permalink to &quot;At the end of the day&quot;">​</a></h3><p><em>At closing: cash drawer, sales of the day.</em></p><ul><li>“Does my till balance tonight?”</li><li>“How did my customers pay today?”</li><li>“What are my five best sellers today?”</li></ul><h3 id="at-the-end-of-the-week" tabindex="-1">At the end of the week <a class="header-anchor" href="#at-the-end-of-the-week" aria-label="Permalink to &quot;At the end of the week&quot;">​</a></h3><p><em>On Sunday evening or Monday morning: the review of the past week.</em></p><ul><li>“Which products sold the least last week?”</li><li>“Which products earned me the most margin last week?”</li><li>“Did my margin drop last week, and why?”</li></ul><h3 id="at-the-end-of-the-month" tabindex="-1">At the end of the month <a class="header-anchor" href="#at-the-end-of-the-month" aria-label="Permalink to &quot;At the end of the month&quot;">​</a></h3><p><em>In the first days of the month: the review of the month just ended.</em></p><ul><li>“What was my margin last month?”</li><li>“Were there any cash discrepancies last month?”</li></ul><h2 id="grocery-store" tabindex="-1">Grocery store <a class="header-anchor" href="#grocery-store" aria-label="Permalink to &quot;Grocery store&quot;">​</a></h2><h3 id="in-the-morning-1" tabindex="-1">In the morning <a class="header-anchor" href="#in-the-morning-1" aria-label="Permalink to &quot;In the morning&quot;">​</a></h3><p><em>Before opening: where do things stand after yesterday?</em></p><ul><li>“What is out of stock or nearly out in my inventory?”</li><li>“What should I order this week?”</li><li>“Am I waiting for any deliveries from my suppliers?”</li></ul><h3 id="at-the-end-of-the-day-1" tabindex="-1">At the end of the day <a class="header-anchor" href="#at-the-end-of-the-day-1" aria-label="Permalink to &quot;At the end of the day&quot;">​</a></h3><p><em>At closing: cash drawer, sales of the day.</em></p><ul><li>“Does my till balance tonight?”</li></ul><h3 id="at-the-end-of-the-week-1" tabindex="-1">At the end of the week <a class="header-anchor" href="#at-the-end-of-the-week-1" aria-label="Permalink to &quot;At the end of the week&quot;">​</a></h3><p><em>On Sunday evening or Monday morning: the review of the past week.</em></p><ul><li>“How much expired stock did I throw away last week?”</li><li>“How much is my stock worth?”</li><li>“Which product earned me the most margin last week?”</li><li>“Which product ties up the most money in my stock?”</li></ul><h3 id="at-the-end-of-the-month-1" tabindex="-1">At the end of the month <a class="header-anchor" href="#at-the-end-of-the-month-1" aria-label="Permalink to &quot;At the end of the month&quot;">​</a></h3><p><em>In the first days of the month: the review of the month just ended.</em></p><ul><li>“How much do I owe my suppliers, and are any invoices overdue?”</li><li>“What was my margin last month?”</li></ul><h2 id="bakery" tabindex="-1">Bakery <a class="header-anchor" href="#bakery" aria-label="Permalink to &quot;Bakery&quot;">​</a></h2><h3 id="in-the-morning-2" tabindex="-1">In the morning <a class="header-anchor" href="#in-the-morning-2" aria-label="Permalink to &quot;In the morning&quot;">​</a></h3><p><em>Before opening: where do things stand after yesterday?</em></p><ul><li>“Are my tills connected?”</li><li>“What sold best last week?”</li></ul><h3 id="at-the-end-of-the-day-2" tabindex="-1">At the end of the day <a class="header-anchor" href="#at-the-end-of-the-day-2" aria-label="Permalink to &quot;At the end of the day&quot;">​</a></h3><p><em>At closing: cash drawer, sales of the day.</em></p><ul><li>“At what time did I have the most customers last week?”</li><li>“Were there any cash discrepancies last week?”</li></ul><h3 id="at-the-end-of-the-week-2" tabindex="-1">At the end of the week <a class="header-anchor" href="#at-the-end-of-the-week-2" aria-label="Permalink to &quot;At the end of the week&quot;">​</a></h3><p><em>On Sunday evening or Monday morning: the review of the past week.</em></p><ul><li>“How much did I make last week?”</li><li>“What was my average basket last week?”</li><li>“Which products sold the least last week?”</li><li>“What share of my sales did the viennoiseries (croissants, pains au chocolat) represent last week?”</li></ul><h3 id="at-the-end-of-the-month-2" tabindex="-1">At the end of the month <a class="header-anchor" href="#at-the-end-of-the-month-2" aria-label="Permalink to &quot;At the end of the month&quot;">​</a></h3><p><em>In the first days of the month: the review of the month just ended.</em></p><ul><li>“How much did I make last month?”</li><li>“What was my margin last month?”</li></ul><h2 id="clothing-shop" tabindex="-1">Clothing shop <a class="header-anchor" href="#clothing-shop" aria-label="Permalink to &quot;Clothing shop&quot;">​</a></h2><h3 id="in-the-morning-3" tabindex="-1">In the morning <a class="header-anchor" href="#in-the-morning-3" aria-label="Permalink to &quot;In the morning&quot;">​</a></h3><p><em>Before opening: where do things stand after yesterday?</em></p><ul><li>“How much did I make yesterday compared with the day before?”</li><li>“Which items are almost out of stock?”</li></ul><h3 id="at-the-end-of-the-day-3" tabindex="-1">At the end of the day <a class="header-anchor" href="#at-the-end-of-the-day-3" aria-label="Permalink to &quot;At the end of the day&quot;">​</a></h3><p><em>At closing: cash drawer, sales of the day.</em></p><ul><li>“Does my till balance tonight?”</li><li>“What are my five best-selling items today?”</li></ul><h3 id="at-the-end-of-the-week-3" tabindex="-1">At the end of the week <a class="header-anchor" href="#at-the-end-of-the-week-3" aria-label="Permalink to &quot;At the end of the week&quot;">​</a></h3><p><em>On Sunday evening or Monday morning: the review of the past week.</em></p><ul><li>“Which items are sitting in stock without selling?”</li><li>“What should I restock first?”</li><li>“Which item earned me the most margin last week?”</li><li>“How much is my stock worth?”</li></ul><h3 id="at-the-end-of-the-month-3" tabindex="-1">At the end of the month <a class="header-anchor" href="#at-the-end-of-the-month-3" aria-label="Permalink to &quot;At the end of the month&quot;">​</a></h3><p><em>In the first days of the month: the review of the month just ended.</em></p><ul><li>“How much did I make last month, by category?”</li><li>“How much did I lose to breakage and theft last month?”</li></ul><h2 id="several-stores" tabindex="-1">Several stores <a class="header-anchor" href="#several-stores" aria-label="Permalink to &quot;Several stores&quot;">​</a></h2><h3 id="in-the-morning-4" tabindex="-1">In the morning <a class="header-anchor" href="#in-the-morning-4" aria-label="Permalink to &quot;In the morning&quot;">​</a></h3><p><em>Before opening: where do things stand after yesterday?</em></p><ul><li>“How much did I make yesterday across all my stores?”</li></ul><h3 id="at-the-end-of-the-week-4" tabindex="-1">At the end of the week <a class="header-anchor" href="#at-the-end-of-the-week-4" aria-label="Permalink to &quot;At the end of the week&quot;">​</a></h3><p><em>On Sunday evening or Monday morning: the review of the past week.</em></p><ul><li>“Compare my stores over last week.”</li><li>“Which store had the highest average basket last week?”</li></ul><h3 id="at-the-end-of-the-month-4" tabindex="-1">At the end of the month <a class="header-anchor" href="#at-the-end-of-the-month-4" aria-label="Permalink to &quot;At the end of the month&quot;">​</a></h3><p><em>In the first days of the month: the review of the month just ended.</em></p><ul><li>“Which store had the best margin rate last month?”</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/VendoraSystem-docs/aide/en/guide/reglages/brancher-votre-assistant-ia">Connect your AI assistant</a></li><li><a href="/VendoraSystem-docs/aide/en/guide/reglages/bilan-automatique">Get an automatic daily summary</a></li></ul>',66))])}const w=o(d,[["render",m]]);export{g as __pageData,w as default};
